// Payload Laravel: { event, data: { recipients: [{ phone, message, status, ... }] } }
const root = $input.first().json || {};
const payload = root.body && typeof root.body === 'object' ? root.body : root;

if (payload.event !== 'reminder_closing') {
  return [];
}

const recipients = Array.isArray(payload.data?.recipients) ? payload.data.recipients : [];

return recipients
  .map((r) => {
    const status = String(r.status || 'active').toLowerCase();
    if (status !== 'active') return null;
    let phone = String(r.phone || '').replace(/\D+/g, '');
    if (phone.startsWith('0')) phone = '62' + phone.slice(1);
    if (phone.startsWith('8') && !phone.startsWith('62')) phone = '62' + phone;
    const message = String(r.message || '').trim();
    if (!phone || phone.length < 11 || !message) return null;
    return {
      json: {
        employee_id: r.employee_id ?? null,
        name: r.name || '',
        branch_name: r.branch_name || '',
        status: 'active',
        phone,
        chatId: `${phone}@c.us`,
        message,
      },
    };
  })
  .filter(Boolean);
